# Ciência Política — lote L14, terceira leva (parte 3: Q09–Q11)
TG="e"
Q = []
TAILS=[" Essa seria a posição predominante na literatura especializada de ciência política.",
 " Trata-se de entendimento consolidado na teoria política contemporânea.",
 " Tal conclusão decorreria, segundo esse entendimento, das características do arranjo institucional descrito.",
 " Essa seria a leitura mais aceita entre os estudiosos do tema."]
SHORT=[" Isso é consenso na área."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o entendimento usual."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.93*len(C) and gap > 14: return E+SHORT[i%len(SHORT)]
    return E
FD={"tipo":"doutrina","ref":"doutrina de ciência política; CF","versao":"conhecimento do autor","conferida":"conhecimento"}
FJ={"tipo":"jurisprudencia","ref":"jurisprudência e legislação eleitoral","versao":"conhecimento do autor","conferida":"conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag, jur=False, lei=False):
    ex = {}
    if lei: ex["fonte"]={"tipo":"lei","ref":"CF; leis eleitorais","versao":"vigente","conferida":"conhecimento"}
    elif jur: ex["fonte"]=FJ; ex["risco"]=["jurisprudencia_conhecimento"]
    else: ex["fonte"]=FD; ex["risco"]=["doutrina_conhecimento"]
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n={}
def X(q,atom,padE,dif,C,E,com,terro,jur=False,lei=False):
    _n[q]=_n.get(q,0)+1
    P(f"Q{q:02d}",[str(atom)],"conceito_correto",padE,dif,C,E,com,terro,f"{TG}{q:02d}{_n[q]}",jur=jur,lei=lei)
# ---------- Q09 teoria e formação do Estado (átomos 47, 48)
X(9,47,"confusao_instituto",3,"Para Max Weber, o Estado moderno é a comunidade humana que, dentro de um território, reivindica com êxito o monopólio do uso legítimo da força física.","Para Max Weber, o Estado moderno é a comunidade humana que, dentro de um território, reivindica a propriedade dos meios de produção em nome da classe dominante.","Weber.","atribui tese marxista")
X(9,47,"confusao_instituto",4,"Para Jellinek, o Estado possui três elementos: povo, território e poder soberano (ou governo), e a soberania, em sentido jurídico, é a competência de determinar-se a si mesmo.","Para Jellinek, o Estado possui um único elemento, o poder, e o povo e o território são meros efeitos da vontade do governante.","Jellinek.","reduz elementos")
X(9,47,"confusao_instituto",4,"Para Kelsen, o Estado é identificado com a ordem jurídica, e a validade das normas decorre de uma norma fundamental pressuposta, e não de fatos sociais ou de valores morais.","Para Kelsen, o Estado é anterior ao direito e a validade das normas decorre dos valores morais e da vontade do soberano.","Kelsen.","inverte tese")
X(9,47,"confusao_instituto",4,"Para Carl Schmitt, soberano é quem decide sobre o estado de exceção, e o critério do político é a distinção entre amigo e inimigo.","Para Carl Schmitt, o soberano é quem se submete ao estado de exceção, e o critério do político é o consenso racional entre os cidadãos.","Schmitt.","inverte conceitos")
X(9,47,"confusao_instituto",4,"Para Hegel, o Estado é a efetivação da liberdade ética, superando a sociedade civil, esfera dos interesses particulares, e realizando o universal.","Para Hegel, o Estado é um mal necessário, meramente instrumental para proteger a propriedade da sociedade civil, sem finalidade ética.","Hegel.","atribui visão liberal-instrumental")
X(9,47,"confusao_instituto",4,"Para Rawls, os princípios de justiça são os que seriam escolhidos por pessoas sob o véu da ignorância, e incluem a igualdade de liberdades básicas e o princípio da diferença; para Nozick, o Estado legítimo é o Estado mínimo.","Para Rawls, o Estado legítimo é o Estado mínimo, limitado à proteção contra a força e o roubo; para Nozick, os princípios de justiça decorrem do véu da ignorância e do princípio da diferença.","Rawls; Nozick.","troca os autores")
X(9,47,"excecao_omitida",3,"Para o marxismo clássico, o Estado é instrumento da classe dominante, e Gramsci amplia a análise ao destacar a hegemonia, que combina coerção e consenso e envolve a sociedade civil.","Para o marxismo clássico, o Estado é entidade neutra, acima das classes, e Gramsci sustenta que a hegemonia dispensa o consenso e se funda apenas na coerção.","Marx; Gramsci.","inverte tese")
X(9,47,"confusao_instituto",3,"Para Hobbes, no estado de natureza há uma guerra de todos contra todos, e os indivíduos pactuam a criação do Estado soberano para assegurar a paz e a segurança; para Locke, o governo se funda no consentimento e é limitado pelos direitos naturais.","Para Hobbes, no estado de natureza há harmonia e os indivíduos pactuam a criação do Estado apenas para ampliar o lazer; para Locke, o governo é absoluto e ilimitado pelos direitos naturais.","Hobbes; Locke.","inverte teses contratualistas")
X(9,48,"confusao_instituto",4,"Para Norbert Elias, a formação do Estado moderno decorre de processos de monopolização da violência física e da tributação, associados à competição entre senhores feudais.","Para Norbert Elias, a formação do Estado moderno decorre da dispersão dos monopólios da violência e da tributação entre múltiplas autoridades locais, em um processo de descentralização.","Elias.","inverte processo")
X(9,48,"confusao_instituto",4,"Para Charles Tilly, a guerra fez o Estado e o Estado fez a guerra, ou seja, a preparação para o conflito armado estimulou a extração de recursos e a construção de burocracias.","Para Charles Tilly, a guerra não teve papel na formação do Estado moderno, que decorre exclusivamente da expansão do comércio pacífico.","Tilly.","nega papel da guerra")
X(9,48,"confusao_instituto",4,"Para Michael Mann, o poder infraestrutural do Estado é a capacidade de penetrar a sociedade civil e implementar decisões, e distingue-se do poder despótico, que é a margem de ação das elites estatais sem negociação com grupos sociais.","Para Michael Mann, o poder infraestrutural do Estado é a margem de ação das elites estatais sem negociação, e distingue-se do poder despótico, que é a capacidade de penetrar a sociedade civil.","Mann.","troca os conceitos")
X(9,48,"confusao_instituto",4,"Theda Skocpol defende que se deve trazer o Estado de volta à análise, tratando-o como ator com autonomia relativa, e não como mero reflexo de interesses de classes ou grupos.","Theda Skocpol defende que o Estado deve ser tratado como mero reflexo dos interesses de classes ou grupos, sem autonomia alguma.","Skocpol.","nega autonomia do Estado")
X(9,48,"excecao_omitida",3,"No Brasil, Simon Schwartzman associa o Estado a uma tradição patrimonialista, e Raymundo Faoro, em Os donos do poder, descreve um estamento burocrático que se apropria do poder desde Portugal.","No Brasil, Raymundo Faoro, em Os donos do poder, afirma que o Estado brasileiro sempre foi instrumento de uma burguesia industrial, sem relação com o patrimonialismo português.","Faoro.","inverte tese de Faoro")
X(9,48,"confusao_instituto",4,"No corporativismo estatal, típico do Estado Novo, sindicatos e associações são reconhecidos e controlados pelo Estado, que organiza a representação de interesses.","No corporativismo estatal, típico do Estado Novo, sindicatos e associações são livres, múltiplos e independentes do Estado.","Corporativismo.","inverte relação com o Estado")
# ---------- Q10 Estado brasileiro (átomos 49, 50)
X(10,49,"troca_numero",2,"A Independência do Brasil foi proclamada em 1822, e D. Pedro I foi coroado Imperador no mesmo ano, em um processo em que se preservou a monarquia, a escravidão e a unidade territorial.","A Independência do Brasil foi proclamada em 1808, com a chegada da família real, e levou à imediata abolição da escravidão e à instauração da República.","Independência.","altera data e consequências")
X(10,49,"troca_numero",2,"A abolição da escravidão no Brasil ocorreu em 13 de maio de 1888, pela Lei Áurea, e a República foi proclamada em 15 de novembro de 1889.","A abolição da escravidão no Brasil ocorreu em 15 de novembro de 1889, e a República foi proclamada em 13 de maio de 1888.","Abolição e República.","inverte datas")
X(10,49,"excecao_omitida",3,"A Constituição de 1891 conferiu aos Estados ampla autonomia, inclusive para cobrar imposto de exportação, e deu ao Estado brasileiro feição federativa, em contraste com a centralização do Império.","A Constituição de 1891 manteve a centralização do Império, retirando dos Estados qualquer autonomia tributária e administrativa.","Federalismo de 1891.","nega autonomia estadual")
X(10,49,"excecao_omitida",3,"O Ato Adicional de 1834 criou as Assembleias Legislativas provinciais e substituiu a Regência trina pela Regência una, em um movimento de descentralização que foi revertido pela Lei de Interpretação de 1840.","O Ato Adicional de 1834 extinguiu as Assembleias provinciais e reforçou a centralização, e foi ampliado pela Lei de Interpretação de 1840.","Ato Adicional.","inverte descentralização")
X(10,50,"troca_numero",3,"A Constituição de 1934 constitucionalizou a Justiça Eleitoral e o voto feminino, os direitos sociais e trabalhistas, e teve curta duração, sendo substituída pela Carta de 1937.","A Constituição de 1934 vigorou por longo período, até ser substituída apenas pela Constituição de 1946.","Constituição de 1934.","altera duração e sucessora")
X(10,50,"troca_numero",3,"A Constituição de 1946 restabeleceu a democracia após o Estado Novo, com eleições diretas, pluripartidarismo e federalismo, e vigorou formalmente até 1967, com alterações introduzidas pelos atos institucionais após 1964.","A Constituição de 1946 foi outorgada por Vargas em 1937 e consolidou o Estado Novo, com partido único e eleições indiretas.","Constituição de 1946.","atribui caráter do Estado Novo")
X(10,50,"troca_numero",3,"O Ato Institucional n. 2, de 1965, extinguiu os partidos existentes e estabeleceu eleições indiretas para Presidente da República, e a organização do bipartidarismo, com a Arena e o MDB, decorreu do Ato Complementar n. 4, do mesmo ano.","O Ato Institucional n. 2, de 1965, restabeleceu o pluripartidarismo e as eleições diretas para Presidente da República.","AI-2.","inverte conteúdo")
X(10,50,"troca_numero",3,"A Lei da Anistia, de 1979, e a reforma partidária do mesmo ano, que extinguiu o bipartidarismo, precederam o retorno dos governadores eleitos diretamente, em 1982.","A Lei da Anistia, de 1979, manteve o bipartidarismo até 1990, e os governadores só voltaram a ser eleitos diretamente a partir de 1994.","Abertura política.","altera datas e alcance")
X(10,50,"excecao_omitida",3,"A Emenda Dante de Oliveira, que propunha eleições diretas para Presidente da República, foi rejeitada pela Câmara dos Deputados em 1984, apesar da ampla mobilização das Diretas Já; Tancredo Neves foi eleito indiretamente, pelo Colégio Eleitoral, em 1985.","A Emenda Dante de Oliveira foi aprovada pela Câmara dos Deputados em 1984, e as eleições diretas para Presidente da República ocorreram em 1985.","Diretas Já.","inverte resultado")
X(10,50,"troca_numero",3,"A Constituição de 1988 foi promulgada em 5 de outubro de 1988 pela Assembleia Nacional Constituinte, instalada em 1987, e a primeira eleição direta para Presidente da República após o regime militar ocorreu em 1989.","A Constituição de 1988 foi outorgada pelo Presidente José Sarney, e a primeira eleição direta para Presidente da República após o regime militar ocorreu em 1994.","Constituição de 1988.","altera natureza e data")
X(10,50,"excecao_omitida",3,"O Plano Real foi lançado em 1994, no governo Itamar Franco, e a EC 16/1997 permitiu a reeleição para os cargos de Presidente da República, Governadores e Prefeitos para um único período subsequente.","A EC 16/1997 vedou a reeleição para os cargos de Presidente da República, Governadores e Prefeitos, e o Plano Real foi lançado em 1986, no governo Sarney.","EC 16/1997; Plano Real.","inverte reeleição e data")
# ---------- Q11 história do voto e dos partidos (átomos 51, 52)
X(11,51,"troca_numero",3,"O voto feminino foi instituído no Brasil pelo Código Eleitoral de 1932, e a Constituição de 1934 o confirmou, tornando-o obrigatório apenas para mulheres que exercessem função pública remunerada.","O voto feminino foi instituído no Brasil pela Constituição de 1891, e tornou-se obrigatório para todas as mulheres em 1932.","Voto feminino.","altera data e obrigatoriedade")
X(11,51,"troca_numero",3,"A Constituição de 1988 facultou o voto aos analfabetos e aos maiores de dezesseis e menores de dezoito anos, o que ampliou o eleitorado em relação às Constituições anteriores.","A Constituição de 1988 proibiu o voto dos analfabetos e dos maiores de dezesseis e menores de dezoito anos, o que restringiu o eleitorado em relação às anteriores.","Voto na CF/88.","inverte ampliação")
X(11,51,"excecao_omitida",3,"A Emenda Constitucional n. 25/1985 restabeleceu o voto direto para Presidente da República, instituiu o voto dos analfabetos.","A Emenda Constitucional n. 25/1985 suprimiu o voto dos analfabetos e manteve as eleições indiretas para Presidente da República.","EC 25/1985.","inverte conteúdo")
X(11,51,"excecao_omitida",4,"A Lei Saraiva, de 1881, instituiu o voto direto para o Império, mas elevou a renda mínima exigida e excluiu os analfabetos, o que reduziu significativamente o eleitorado.","A Lei Saraiva, de 1881, instituiu o voto universal e secreto para o Império, e ampliou o eleitorado por incluir os analfabetos.","Lei Saraiva.","inverte efeito")
X(11,51,"excecao_omitida",3,"O voto secreto foi introduzido no Brasil pelo Código Eleitoral de 1932, e o voto eletrônico foi utilizado pela primeira vez em 1996, em municípios com mais de duzentos mil eleitores, tornando-se universal em 2000.","O voto secreto foi introduzido no Brasil pela Constituição de 1824, e o voto eletrônico foi utilizado pela primeira vez em 1996, em todo o território nacional.","Voto secreto e urna eletrônica.","altera datas e abrangência")
X(11,52,"troca_numero",3,"Em 1979, a Lei Orgânica dos Partidos Políticos extinguiu o bipartidarismo, o MDB deu origem ao PMDB e a Arena ao PDS, e novos partidos foram criados, como o PT e o PDT.","Em 1979, a Lei Orgânica dos Partidos Políticos instituiu o bipartidarismo, a Arena deu origem ao PMDB e o MDB ao PDS.","Reforma partidária de 1979.","inverte sucessões")
X(11,52,"excecao_omitida",3,"No Império, os dois principais partidos, o Conservador e o Liberal, alternavam-se no poder por ação do Imperador, mas não se distinguiam, na prática, por programas ideológicos muito definidos.","No Império, os partidos Conservador e Liberal tinham programas ideológicos rigidamente distintos e se alternavam no poder por vitória eleitoral competitiva, sem interferência do Imperador.","Partidos do Império.","nega papel do Imperador")
X(11,52,"excecao_omitida",3,"Na Primeira República, os partidos eram predominantemente estaduais, como o Partido Republicano Paulista (PRP) e o Partido Republicano Mineiro (PRM), e não havia partidos nacionais estáveis.","Na Primeira República, os partidos eram predominantemente nacionais e disputavam as eleições com programas ideológicos, e o PRP e o PRM eram os dois únicos partidos do país.","Partidos da Primeira República.","inverte natureza")
X(11,52,"excecao_omitida",3,"Entre 1945 e 1964, o sistema partidário brasileiro foi multipartidário, com destaque para PSD, UDN e PTB, e foi extinto pelo Ato Institucional n. 2, em 1965.","Entre 1945 e 1964, o sistema partidário brasileiro foi de partido único, o PSD, e foi extinto pelo Ato Institucional n. 5, em 1968.","Sistema partidário de 1945-1964.","inverte natureza")
X(11,52,"troca_numero",3,"O PT foi fundado em 1980, o PSDB, em 1988, e o PMDB passou a denominar-se MDB em 2017, retomando o nome da agremiação original do bipartidarismo.","O PT foi fundado em 1964, o PSDB, em 1950, e o PMDB passou a denominar-se Arena em 2017, retomando o nome original.","Partidos pós-1979.","altera datas e nomes")
